```java
package org.apache.accumulo.core.summary;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Predicate;
import java.util.function.Function;

import org.apache.accumulo.core.util.CompletableFutureUtil;

public class Test {
    public static void main(String args[]) throws Exception{
        ExecutorService es = Executors.newFixedThreadPool(2);

        Predicate<Long> test = num -> num >=10;

        Function<Long, CompletableFuture<Long>> step = num -> {
            System.out.println(num+" Step thread "+Thread.currentThread().getName());

            var cf = CompletableFuture.supplyAsync(() ->{ 
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    // TODO Auto-generated catch block
                    e.printStackTrace();
                }
                System.out.println(num+" Supply async thread "+Thread.currentThread().getName());
                return num;
            }, es);

            cf = cf.thenApply(l -> {
                System.out.println(l+" Then apply thread "+Thread.currentThread().getName());
                return l+1;
            });

            return cf;
